func:
// Importati acest nod in ACELASI tab cu controllerul Telegram Victron.
// Iesirea se conecteaza la nodul existent "Telegram commands + replies".
// Nu introduce token/chat ID aici si NU creeaza alt poller.
let p=msg.payload;
if(typeof p==="string"){try{p=JSON.parse(p);}catch(e){return null;}}
if(!p||typeof p!=="object"||p.source!=="huawei_v2_ha")return null;
const titles={
 actual_discharge:"Huawei descarca efectiv",
 anti_transfer_block:"Anti-transfer activ - Huawei blocat",
 data_fault:"Telemetrie invalida / veche",
 huawei_soc_stop:"Huawei a atins pragul de SOC",
 anti_import_on:"Anti-import Huawei activ"
};
const kind=String(p.event||"");
if(!Object.prototype.hasOwnProperty.call(titles,kind))return null;
const now=Date.now(),ts=Number(p.ts)*1000;
if(!Number.isFinite(ts)||ts>now+30000||now-ts>120000)return null;
const last=flow.get("huawei_v2_tg_bridge_last_sent")||{};
const cooldown=(kind==="data_fault"?20:kind==="anti_transfer_block"?10:15)*60000;
if(now-Number(last[kind]||0)<cooldown)return null;
function n(v){const x=Number(v);return Number.isFinite(x)?String(Math.round(x)):"N/A";}
let lines=["HUAWEI v2 - "+titles[kind],
 "SOC Hailei/PACE: "+n(p.h_soc)+"% | Huawei: "+n(p.hu_soc)+"%",
 "Retea: "+n(p.grid_w)+" W (+import / -export)",
 "Hailei: "+n(p.hailei_w)+" W | Huawei: "+n(p.huawei_w)+" W",
 "Limita Huawei: "+n(p.discharge_limit_w)+" W",
 "Motiv: "+String(p.reason||"N/A").slice(0,60)];
if(kind==="actual_discharge")lines.push("Puterea Huawei negativa confirmata; nu confunda limita W cu descarcarea masurata.");
if(kind==="anti_transfer_block")lines.push("Protectie activa: HA import >250W, Hailei incarca; descarcare Huawei oprita preventiv.");
last[kind]=now;flow.set("huawei_v2_tg_bridge_last_sent",last);
return {telegram_internal:true,telegram_command:"__alert",telegram_event_text:lines.join("\n")};
